variables.plan:
{%- set heute = now() -%}
{%- set woche = (heute.date() - strptime(start, '%Y-%m-%d').date()).days // 7 -%}
{%- set saison = obst_saison[heute.month - 1] -%}
{%- set fruit = ['apfel', 'birnen', 'bananen', 'clementinen', 'orangen', 'kaki', 'trauben', 'heidelbeeren', 'himbeeren', 'mango', 'avocado'] -%}
{%- set kein_obst = 'saft|aufstrich|schokol|gefroren|kohl|konfit|joghurt|schorle|nektar|sirup|likör|mus|getrocknet|tee|bonbon|riegel|kuchen|duft|spül|shampoo|essig|quark|chips|froop|havana|club|wein|sekt|vodka|whisk|bier' -%}
{#- Vorrat-Merker: "Name=Datum;Name=Datum", bis zu diesem Datum wird der Artikel nicht erneut eingetragen -#}
{%- set vt = states('input_text.einkauf_vorrat') -%}
{%- set vorrat = namespace(m={}) -%}
{%- for p in (vt.split(';') if vt not in ['unknown', 'unavailable', ''] else []) if '=' in p -%}
{%- if p.split('=')[1] >= heute.date().isoformat() -%}{%- set vorrat.m = dict(vorrat.m, **{p.split('=')[0]: p.split('=')[1]}) -%}{%- endif -%}
{%- endfor -%}
{#- Vom wöchentlichen Kassenbon-Abgleich gepflegte Werte: übliche Grundpreise und Rhythmus je Artikel -#}
{%- set werte = namespace(p={}, r={}) -%}
{%- set pt = states('input_text.einkauf_preise') -%}
{%- for p in (pt.split(';') if pt not in ['unknown', 'unavailable', ''] else []) if '=' in p -%}{%- set werte.p = dict(werte.p, **{p.split('=')[0]: p.split('=')[1] | float(0)}) -%}{%- endfor -%}
{%- set rt = states('input_text.einkauf_rhythmus') -%}
{%- for p in (rt.split(';') if rt not in ['unknown', 'unavailable', ''] else []) if '=' in p -%}{%- set werte.r = dict(werte.r, **{p.split('=')[0]: p.split('=')[1] | int(0)}) -%}{%- endfor -%}
{#- Alle aktuellen Angebote von Marktkauf, REWE und EDEKA, die Freitag/Samstag gelten -#}
{%- set ang = namespace(l=[]) -%}
{%- for s in states.sensor | selectattr('entity_id', 'match', 'sensor\\.marktguru_') | selectattr('attributes.retailer_name', 'defined') | rejectattr('attributes.retailer_name', 'none') -%}
{%- set a = s.attributes -%}
{%- set h = a.retailer_name | lower -%}
{%- set markt = 'Marktkauf' if h.startswith('marktkauf') else ('REWE' if h.startswith('rewe') else ('EDEKA' if h.startswith('edeka') else '')) -%}
{%- set von = (a.valid_from | as_datetime) if a.valid_from else none -%}
{%- set ende = (a.valid_to | as_datetime) if a.valid_to else none -%}
{%- if markt and (von is none or von <= heute + timedelta(days=1)) and (ende is none or ende >= heute + timedelta(hours=18)) -%}
{%- set preis = s.state | float(0) -%}
{%- set alt = a.old_price | float(0) -%}
{%- set ang.l = ang.l + [{'begriff': s.entity_id | regex_replace('^sensor\\.marktguru_(.*)_\\d+_\\d+$', '\\1'), 'markt': markt, 'schluessel': ((markt ~ '|' ~ ((a.product_name or '') | lower) ~ '|' ~ ('%.2f' | format(s.state | float(0)))) | md5)[:6], 'produkt': a.product_name or '', 'text': ((a.brand_name or '') ~ ' ' ~ (a.product_name or '')) | lower, 'preis': preis, 'wert': ((a.grundpreis | float(0)) if a.grundpreis and a.grundpreis_einheit in ['kg', 'l'] else preis), 'gp': (a.grundpreis | float(0)) if a.grundpreis and a.grundpreis_einheit in ['kg', 'l'] else 0, 'gpe': a.grundpreis_einheit or '', 'rabatt': ((1 - preis / alt) * 100) | round | int if alt > preis else 0}] -%}
{%- endif -%}
{%- endfor -%}
{%- set euro = '%.2f' -%}
{%- set out = namespace(l=[]) -%}
{%- for art in artikel -%}
{%- set alle = (werte.r[art.name] if art.name in werte.r and werte.r[art.name] >= 1 else art.alle) -%}
{%- set normal = (werte.p[art.name] if art.name in werte.p and werte.p[art.name] > 0 else (art.normal | default(0))) -%}
{%- set faellig = woche % alle == art.versatz % alle -%}
{%- set gesperrt = art.name in vorrat.m -%}
{%- set best = namespace(gp=0, o=none) -%}
{%- for o in ang.l if art.begriffe is defined and o.begriff in art.begriffe and (art.regel is not defined or o.text is search(art.regel)) -%}
{%- set gp = o.gp if o.gp > 0 else ((o.preis / art.pack) if art.pack is defined else 0) -%}
{%- if gp > 0 and (best.o is none or gp < best.gp) -%}{%- set best.gp = gp -%}{%- set best.o = o -%}{%- endif -%}
{%- endfor -%}
{%- set ersparnis = (1 - best.gp / normal) if best.o is not none and normal > 0 else 0 -%}
{%- set lohnt = ersparnis >= 0.15 -%}
{%- set faktor = [(4 if ersparnis >= 0.30 else 2), art.max_faktor | default(1)] | min if lohnt else 1 -%}
{%- set normal_text = (art.anzahl ~ ' ' ~ art.einheit) if art.anzahl is defined else (art.menge | default('')) -%}
{%- if art.obst is defined -%}
{%- if faellig -%}
{#- Höchstens 5 Obstsorten: je Sorte das beste Angebot, rabattierte zuerst, dann nach Grundpreis -#}
{%- set sorten_namen = {'apfel': 'Äpfel', 'birnen': 'Birnen', 'bananen': 'Bananen', 'clementinen': 'Clementinen', 'orangen': 'Orangen', 'kaki': 'Kaki', 'trauben': 'Trauben', 'heidelbeeren': 'Heidelbeeren', 'himbeeren': 'Himbeeren', 'mango': 'Mango', 'avocado': 'Avocado'} -%}
{%- set tipps = namespace(l=[], sorten=[], schluessel=[]) -%}
{%- set obst = ang.l | selectattr('begriff', 'in', fruit) | list -%}
{%- for o in (obst | selectattr('rabatt', 'gt', 0) | sort(attribute='rabatt', reverse=true) | list) + (obst | selectattr('rabatt', 'eq', 0) | sort(attribute='wert') | list) -%}
{%- if o.begriff not in tipps.sorten and tipps.l | count < 5 and not o.text is search(kein_obst) -%}
{%- set tipps.sorten = tipps.sorten + [o.begriff] -%}
{%- set tipps.schluessel = tipps.schluessel + [o.schluessel] -%}
{%- set tipps.l = tipps.l + [sorten_namen[o.begriff] ~ ' ' ~ (euro | format(o.preis) | replace('.', ',')) ~ ' € (' ~ (('−' ~ o.rabatt ~ ' %, ') if o.rabatt > 0 else '') ~ o.markt ~ ')'] -%}
{%- endif -%}
{%- endfor -%}
{%- set out.l = out.l + [{'name': art.name, 'text': (tipps.l | join('; ')) if tipps.l else ('Saison: ' ~ saison), 'angebot': (1 if tipps.l else 0), 'vorrat': '', 'schluessel': tipps.schluessel}] -%}
{%- endif -%}
{%- elif lohnt and not gesperrt -%}
{%- set o = best.o -%}
{%- set hinweis = 'Angebot ' ~ o.markt ~ ': ' ~ (o.produkt | title) ~ ' ' ~ (euro | format(o.preis) | replace('.', ',')) ~ ' € (' ~ (euro | format(best.gp) | replace('.', ',')) ~ ' €/' ~ (o.gpe or art.je | default('Einheit')) ~ ', −' ~ (ersparnis * 100) | round | int ~ ' % ggü. üblich)' -%}
{%- set menge = ((art.anzahl * faktor) ~ ' ' ~ art.einheit) if art.anzahl is defined else normal_text -%}
{%- set reichweite = faktor * alle -%}
{%- set out.l = out.l + [{'name': art.name, 'text': ([menge, hinweis, ('Vorrat für ' ~ reichweite ~ ' Wochen') if faktor > 1 else ''] | select | join(' · ')), 'angebot': 1, 'vorrat': (heute.date() + timedelta(days=reichweite * 7 - 1)).isoformat() if faktor > 1 else '', 'schluessel': [o.schluessel]}] -%}
{%- elif faellig and not gesperrt -%}
{%- set out.l = out.l + [{'name': art.name, 'text': normal_text, 'angebot': 0, 'vorrat': '', 'schluessel': []}] -%}
{%- endif -%}
{%- endfor -%}
{%- set merker = namespace(m=vorrat.m) -%}
{%- for e in out.l if e.vorrat -%}{%- set merker.m = dict(merker.m, **{e.name: e.vorrat}) -%}{%- endfor -%}
{%- set teile = namespace(l=[]) -%}
{%- for k, v in merker.m.items() -%}{%- set teile.l = teile.l + [k ~ '=' ~ v] -%}{%- endfor -%}
{#- Schlüssel der übernommenen Angebote: die Angebotskarte blendet sie aus -#}
{%- set ks = namespace(l=[]) -%}
{%- for e in out.l -%}{%- set ks.l = ks.l + e['schluessel'] -%}{%- endfor -%}
{{ {'eintraege': out.l, 'vorrat': teile.l | join(';'), 'uebernommen': (ks.l | unique | list)[:36] | join(',')} | tojson }}

data.message:
{%- set neu = namespace(l=[]) -%}
{%- for e in plan.eintraege if not e.vorrat and (e.name | lower) not in offene -%}{%- set neu.l = neu.l + [e.name] -%}{%- endfor -%}
{%- set vorrat = plan.eintraege | selectattr('vorrat', 'ne', '') | list -%}
{%- if neu.l -%}Neu auf der Liste: {{ neu.l | join(', ') }}.{%- endif -%}
{%- for e in vorrat %}
{{ '\n' if loop.first and neu.l else '' }}Auf Vorrat: {{ e.name }} – {{ e.text }}
{%- endfor -%}

