{%- set d = strptime(p.date, '%Y-%m-%d') -%}
{%- set essen = p.dinner | map(attribute='name') | join(', ') -%}
{%- if not essen and not tage.vor -%}{%- set tage.vor = p.date -%}{%- endif -%}
{%- set tage.l = tage.l + [{'d': p.date, 'text': wt[d.weekday()] ~ ', ' ~ d.strftime('%d.%m.'), 'essen': essen}] -%}
{%- endfor -%}
{%- for r in res[:5] -%}
{%- set o = r.offer -%}
{%- set h = (o.retailer or '') | lower -%}
{%- set markt = 'Marktkauf' if h.startswith('marktkauf') else ('REWE' if h.startswith('rewe') else ('EDEKA' if h.startswith('edeka') else (o.retailer or ''))) -%}
{%- set preis = '%.2f' | format(o.price | float(0)) | replace('.', ',') -%}
